-- Every article carries a free public domain photo: the picture at the top of
-- the article, the thumbnail on its tile, and the image a shared link shows.
-- The file itself lives in the site (site/assets/articles/<slug>.jpg, 1200x630)
-- and the row carries its path, alt text, credit line and the page it came
-- from. docs/articles.md is the guide; tools/article_photos.py finds a photo,
-- and tools/articles_sql.py writes these columns with the rest of the row.
--
-- The update below was generated with:
--   python3 tools/articles_sql.py --photos

alter table public.articles
  add column if not exists photo_url    text,
  add column if not exists photo_alt    text,
  add column if not exists photo_credit text,
  add column if not exists photo_source text;

comment on column public.articles.photo_url is
  'Site path of the article''s public domain photo (1200x630 JPEG), e.g. /assets/articles/<slug>.jpg';
comment on column public.articles.photo_alt is 'What is in the photo, one sentence';
comment on column public.articles.photo_credit is 'Photo by <name> via <source>, <CC0 or Public domain>';
comment on column public.articles.photo_source is 'The page the photo came from';

update public.articles as a set
  photo_url    = v.photo_url,
update public.articles as a set
  photo_url    = v.photo_url,
  photo_alt    = v.photo_alt,
  photo_credit = v.photo_credit,
  photo_source = v.photo_source
